insert into profiles (id, owner_user_id, type, handle, display_name, bio, i18n, avatar_url, banner_url, is_verified, verified_at) values ('33489b60-d8df-508d-ab96-0afa372d95c2', '4e65c5f6-ba27-5184-8e03-e6d441e74096', 'creator', 'haulingempire', 'Hauling Empire', 'A truck tycoon game for iOS and Android. Pick loads, plan routes, hire drivers and grow one van into a logistics empire. Fair play: no gems, no energy timers.', '{"bio":{"en":"A truck tycoon game for iOS and Android. Pick loads, plan routes, hire drivers and grow one van into a logistics empire. Fair play: no gems, no energy timers.","es":"Un juego de magnate de camiones para iOS y Android. Elige cargas, planifica rutas, contrata conductores y convierte una furgoneta en un imperio logístico. Juego limpio: sin gemas ni temporizadores de energía.","tr":"iOS ve Android için bir tır şirketi oyunu. Yük seç, rota planla, şoför işe al ve tek bir kamyoneti lojistik imparatorluğuna dönüştür. Adil oyun: elmas yok, enerji bekleme süresi yok."},"kind":{"en":"Indie game","es":"Juego indie","tr":"Bağımsız oyun"},"mono":null}', 'https://promovote.com/media/hauling-empire-icon.jpg', 'https://promovote.com/media/hauling-empire-poster.jpg', 1, '2026-10-06T00:00:00.000Z');
