insert into profiles (id, owner_user_id, type, handle, display_name, bio, i18n, avatar_url, banner_url, is_verified, verified_at) values ('87832b9d-da00-52cc-bb8e-5ee93f2f8462', '1e1476b2-bfab-5136-b0db-1fdf3f2caaa9', 'creator', 'poleris', 'Poleris', 'A calm daily practice for manifestation. Write one intention, then take a two minute ritual each day: read your affirmation, give thanks, see it. Includes a 21 day journey, breathing and guided meditation.', '{"bio":{"en":"A calm daily practice for manifestation. Write one intention, then take a two minute ritual each day: read your affirmation, give thanks, see it. Includes a 21 day journey, breathing and guided meditation.","es":"Una práctica diaria y tranquila para manifestar. Escribe una intención y haz un ritual de dos minutos cada día: lee tu afirmación, agradece y visualízalo. Incluye un viaje de 21 días, respiración y meditación guiada.","tr":"Niyet ve manifest için sakin bir günlük pratik. Bir niyet yaz, sonra her gün iki dakikalık ritüelini yap: olumlamanı oku, şükret, gör. 21 günlük yolculuk, nefes egzersizi ve rehberli meditasyon da var."},"kind":{"en":"Wellness app","es":"App de bienestar","tr":"Sağlıklı yaşam uygulaması"},"mono":null}', 'https://promovote.com/media/poleris-icon.jpg', 'https://promovote.com/media/poleris-poster.jpg', 1, '2026-10-06T00:00:00.000Z');
